using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "StarBeamCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/StarBeamCustomDescription", order = 0)]
public class StarBeamCustomDescription : PurifyCorruptWithMultiplierCustomDescription
{
	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		StarBeamAction starBeamAction = battleAction as StarBeamAction;
		return Smart.Format(base.GetRawLocalizedDescription(battleAction), starBeamAction.StarShardsAmount);
	}
}
